
import * as N3 from 'n3';
import {
  PREFIXES, allPrefixes, prefixNamespace, curie, labelFor, prunePrefixes,
  subjectJsonLdBody, jsonLdContext, targetPredicates, PROFILE_PATTERNS,
  dedupeTriples, freeBlank, localName,
} from './parse.js';
import { langRank } from './i18n.js';
import { editProfile } from './profile.js';
import { termKey, termOf } from './term.js';

const { DataFactory, Parser, Store } = N3;
const { namedNode, literal } = DataFactory;

// Written INTO THE GRAPH, so it is not translated per session: a title that
// changes spelling with the reader's chrome language would make the same
// document read differently for two people. `edit.duplicateHint` quotes it.
const COPY_SUFFIX = ' (copy)';

const RDF = PREFIXES.rdf;
const RDFS = PREFIXES.rdfs;
const ODRL = PREFIXES.odrl;
const DCT = PREFIXES.dct;
const DCAT = PREFIXES.dcat;
const XSD = PREFIXES.xsd;
const FOAF = PREFIXES.foaf;
const DPV = PREFIXES.dpv;

export function defaultProfile() {
  return editProfile().defaultProfile;
}

const nn = (x) => termOf(x) ?? x;

function objsOf(store, s, p) {
  return store.getQuads(s, namedNode(p), null, null).map((q) => q.object);
}
function objOf(store, s, p) {
  const o = objsOf(store, s, p);
  return o.length ? o[0] : null;
}

export function closureQuads(store, start) {
  const collected = [];
  const seen = new Set();
  const stack = [nn(start)];
  while (stack.length) {
    const s = stack.pop();
    const key = s.termType + ':' + s.value;
    if (seen.has(key)) continue;
    seen.add(key);
    for (const q of store.getQuads(s, null, null, null)) {
      collected.push(q);
      if (q.object.termType === 'BlankNode') stack.push(q.object);
    }
  }
  return collected;
}

export function expandIri(text) {
  if (typeof text !== 'string') return text;
  const t = text.trim();
  if (!t) return '';
  if (/^https?:\/\//.test(t) || t.startsWith('urn:')) return t;
  const m = t.match(/^([\w-]+):(.*)$/);
  if (m) {
    const ns = prefixNamespace(m[1]);
    if (ns) return ns + m[2];
  }
  return t;
}

export function validIriText(s) {
  const v = String(s || '');
  if (!/^[A-Za-z][A-Za-z0-9+.-]*:/.test(v)) return false;
  return !/[\s<>"{}|\\^`]/.test(v);
}

export function mintIri(store, baseIri) {
  let iri = baseIri;
  let i = 2;
  while (store.getQuads(namedNode(iri), null, null, null).length
      || store.getQuads(null, null, namedNode(iri), null).length) {
    iri = baseIri + '-' + i++;
  }
  return iri;
}

const EDIT_COUNTER = { n: 0 };
function mintBlank(store) {
  return freeBlank(store, 'edit-', EDIT_COUNTER);
}

function today() {
  return new Date().toISOString().slice(0, 10);
}

export function removeProp(store, subject, predIri) {
  store.removeQuads(store.getQuads(nn(subject), namedNode(predIri), null, null));
}

export function setLiteral(store, subject, predIri, value, opts = {}) {
  removeProp(store, subject, predIri);
  if (value == null || value === '') return;
  const lit = opts.datatype ? literal(String(value), namedNode(opts.datatype))
    : (opts.lang ? literal(String(value), opts.lang) : literal(String(value)));
  store.addQuad(nn(subject), namedNode(predIri), lit);
}

export function setDisplayedLiteral(store, read, subject, predIri, value, fallbackShape = {}) {
  const next = value == null ? '' : String(value);
  if (!next) { setLiteral(store, subject, predIri, ''); return; }
  const literals = (read ? read.getQuads(nn(subject), namedNode(predIri), null, null) : [])
    .filter((q) => q.object.termType === 'Literal');
  if (literals.length > 1) {
    const target = shownLiteral(literals);
    const shape = literalShape(target.object) || {};
    store.removeQuads([target]);
    store.addQuad(target.subject, target.predicate,
      // eslint-disable-next-line no-nested-ternary
      (shape.lang ? literal(next, shape.lang)
        : (shape.datatype ? literal(next, namedNode(shape.datatype)) : literal(next))),
      target.graph);
    return;
  }
  setLiteral(store, subject, predIri, next,
    literalShape(literals[0] && literals[0].object) || fallbackShape);
}

export function shownLiteral(literalQuads) {
  let best = null;
  let bestRank = Infinity;
  for (const q of literalQuads) {
    const r = langRank(q.object.language || '');
    if (r < bestRank) { bestRank = r; best = q; }
  }
  return best;
}

export function literalShape(o) {
  if (!o || o.termType !== 'Literal') return null;
  if (o.language) return { lang: o.language };
  if (o.datatype && !/#string$/.test(o.datatype.value)) return { datatype: o.datatype.value };
  return {};
}

export function setIri(store, subject, predIri, iri) {
  removeProp(store, subject, predIri);
  const full = expandIri(iri);
  if (!full) return;
  store.addQuad(nn(subject), namedNode(predIri), namedNode(full));
}

export function setConstraint(store, cTerm, { left, operator, right } = {}) {
  if (left !== undefined) setIri(store, cTerm, ODRL + 'leftOperand', left);
  if (operator !== undefined) setIri(store, cTerm, ODRL + 'operator', operator);
  if (right !== undefined) {
    removeProp(store, cTerm, ODRL + 'rightOperand');
    if (right && right.value !== '' && right.value != null) {
      if (right.kind === 'iri') {
        store.addQuad(nn(cTerm), namedNode(ODRL + 'rightOperand'), namedNode(expandIri(right.value)));
      } else {
        const lit = right.datatype ? literal(String(right.value), namedNode(right.datatype))
          : (right.lang ? literal(String(right.value), right.lang) : literal(String(right.value)));
        store.addQuad(nn(cTerm), namedNode(ODRL + 'rightOperand'), lit);
      }
    }
  }
}

export function addConstraint(store, ruleTerm, predIri = ODRL + 'constraint', opts = {}) {
  const c = mintBlank(store);
  store.addQuad(c, namedNode(RDF + 'type'), namedNode(ODRL + 'Constraint'));
  const left = opts.left ? expandIri(opts.left) : '';
  if (left) store.addQuad(c, namedNode(ODRL + 'leftOperand'), namedNode(left));
  const op = opts.operator ? expandIri(opts.operator) : '';
  if (op) store.addQuad(c, namedNode(ODRL + 'operator'), namedNode(op));
  const holder = opts.onAction ? ensureActionNode(store, ruleTerm) : nn(ruleTerm);
  store.addQuad(holder, namedNode(predIri), c);
  return c;
}

// The wrapper shape `odrl:action [ odrl:refinement … ]` exists WITHOUT rdf:value.
// A setAction that does not recognise it falls back on replacing the whole
// odrl:action with a bare IRI, throwing away the purpose binding.
function ensureActionNode(store, permTerm) {
  const p = nn(permTerm);
  let action = objOf(store, p, ODRL + 'action');
  if (!action) {
    action = mintBlank(store);
    store.addQuad(p, namedNode(ODRL + 'action'), action);
    return action;
  }
  const hasValue = objOf(store, action, RDF + 'value');
  const ownQuads = store.getQuads(action, null, null, null).length;
  if (action.termType === 'NamedNode' && !hasValue && ownQuads === 0) {
    store.removeQuads(store.getQuads(p, namedNode(ODRL + 'action'), action, null));
    const node = mintBlank(store);
    store.addQuad(node, namedNode(RDF + 'value'), action);
    store.addQuad(p, namedNode(ODRL + 'action'), node);
    return node;
  }
  return action;
}

export function setPurpose(store, permTerm, { purpose, operator = ODRL + 'eq' } = {}) {
  const p = nn(permTerm);
  const action = objOf(store, p, ODRL + 'action');
  let existing = null;
  if (action) {
    for (const r of objsOf(store, action, ODRL + 'refinement')) {
      const left = objOf(store, r, ODRL + 'leftOperand');
      if (left && left.value === ODRL + 'purpose') { existing = r; break; }
    }
  }
  const full = expandIri(purpose);
  if (!full) {
    if (existing && action) {
      store.removeQuads(store.getQuads(action, namedNode(ODRL + 'refinement'), existing, null));
      if (existing.termType === 'BlankNode') store.removeQuads(closureQuads(store, existing));
    }
    return null;
  }
  const actionNode = ensureActionNode(store, p);
  let c = existing;
  if (!c) {
    c = mintBlank(store);
    store.addQuad(c, namedNode(RDF + 'type'), namedNode(ODRL + 'Constraint'));
    store.addQuad(c, namedNode(ODRL + 'leftOperand'), namedNode(ODRL + 'purpose'));
    store.addQuad(actionNode, namedNode(ODRL + 'refinement'), c);
  }
  setIri(store, c, ODRL + 'operator', operator);
  setIri(store, c, ODRL + 'rightOperand', full);
  return c;
}

export function setAction(store, permTerm, actionIri) {
  const p = nn(permTerm);
  const full = expandIri(actionIri);
  if (!full) return;
  const action = objOf(store, p, ODRL + 'action');
  if (action && (action.termType === 'BlankNode' || objOf(store, action, RDF + 'value'))) {
    removeProp(store, action, RDF + 'value');
    store.addQuad(action, namedNode(RDF + 'value'), namedNode(full));
  } else {
    removeProp(store, p, ODRL + 'action');
    store.addQuad(p, namedNode(ODRL + 'action'), namedNode(full));
  }
}

const targetPreds = targetPredicates;

export function addTarget(store, permTerm, iri) {
  const full = expandIri(iri);
  if (!full) return;
  store.addQuad(nn(permTerm), namedNode(ODRL + 'target'), namedNode(full));
}

export function removeTarget(store, permTerm, iri) {
  const full = expandIri(iri);
  for (const pred of targetPreds(store)) {
    store.removeQuads(store.getQuads(nn(permTerm), namedNode(pred), namedNode(full), null));
  }
}

function addRule(store, policyTerm, { className, pred }, opts = {}) {
  const p = mintBlank(store);
  store.addQuad(p, namedNode(RDF + 'type'), namedNode(ODRL + className));
  store.addQuad(nn(policyTerm), namedNode(ODRL + pred), p);
  if (opts.purposeIri) setPurpose(store, p, { purpose: opts.purposeIri, operator: ODRL + 'eq' });
  if (opts.targetIri) addTarget(store, p, opts.targetIri);
  return p;
}

const ATTACH_CLASS = {
  [ODRL + 'permission']: ODRL + 'Permission',
  [ODRL + 'prohibition']: ODRL + 'Prohibition',
  [ODRL + 'obligation']: ODRL + 'Duty',
  [ODRL + 'duty']: ODRL + 'Duty',
  [ODRL + 'consequence']: ODRL + 'Duty',
};

const KIND_OF_CLASS = {
  [ODRL + 'Permission']: 'permission',
  [ODRL + 'Prohibition']: 'prohibition',
  [ODRL + 'Duty']: 'duty',
};

function ruleClassOf(store, term) {
  const t = nn(term);
  for (const ty of objsOf(store, t, RDF + 'type')) {
    if (KIND_OF_CLASS[ty.value]) return ty.value;
  }
  for (const q of store.getQuads(null, null, t, null)) {
    const k = ATTACH_CLASS[q.predicate.value];
    if (k) return k;
  }
  return '';
}

export function ruleOptions(store) {
  const per = { permission: new Map(), prohibition: new Map(), duty: new Map() };
  const candidates = new Map();
  for (const pred of ATTACH_PREDS) {
    for (const q of store.getQuads(null, namedNode(pred), null, null)) {
      if (q.object.termType === 'NamedNode') candidates.set(q.object.value, q.object);
    }
  }
  for (const className of Object.keys(KIND_OF_CLASS)) {
    for (const q of store.getQuads(null, namedNode(RDF + 'type'), namedNode(className), null)) {
      if (q.subject.termType === 'NamedNode') candidates.set(q.subject.value, q.subject);
    }
  }
  for (const [iri, t] of candidates) {
    const kind = KIND_OF_CLASS[ruleClassOf(store, t)];
    if (!kind || per[kind].has(iri)) continue;
    const provenance = [];
    for (const q of store.getQuads(null, null, t, null)) {
      if (!ATTACH_CLASS[q.predicate.value]) continue;
      const name = labelFor(store, q.subject);
      if (name && !provenance.includes(name)) provenance.push(name);
    }
    per[kind].set(iri, { iri, curie: curie(iri), label: labelFor(store, t), provenance });
  }
  const sort = (m) => [...m.values()].sort((a, b) => a.label.localeCompare(b.label, 'nl'));
  return { permission: sort(per.permission), prohibition: sort(per.prohibition), duty: sort(per.duty) };
}

export function attachCheck(store, policyTerm, predIri, ruleIri) {
  const iri = expandIri(String(ruleIri || '').trim());
  if (!iri || !validIriText(iri)) return { ok: false, reason: 'invalid' };
  const r = namedNode(iri);
  if (!store.getQuads(r, null, null, null).length
      && !store.getQuads(null, null, r, null).length) {
    return { ok: false, reason: 'unknown' };
  }
  const p = nn(policyTerm);
  if (!p) return { ok: false, reason: 'unknown' };
  if (store.getQuads(p, namedNode(predIri), r, null).length) {
    return { ok: false, reason: 'alreadyLinked' };
  }
  const expected = ATTACH_CLASS[predIri];
  const className = ruleClassOf(store, r);
  if (!className || (expected && className !== expected)) return { ok: false, reason: 'wrongKind' };
  return { ok: true };
}

export function attachRule(store, policyTerm, predIri, ruleIri) {
  const verdict = attachCheck(store, policyTerm, predIri, ruleIri);
  if (!verdict.ok) return verdict;
  const r = namedNode(expandIri(String(ruleIri).trim()));
  store.addQuad(nn(policyTerm), namedNode(predIri), r);
  return { ok: true, term: r };
}

const CONSTRAINT_PREDS = [ODRL + 'constraint', ODRL + 'refinement'];

const CONSTRAINT_CLASSES = [ODRL + 'Constraint', ODRL + 'LogicalConstraint'];

function isConstraint(store, term) {
  const t = nn(term);
  if (!t) return false;
  for (const ty of objsOf(store, t, RDF + 'type')) {
    if (CONSTRAINT_CLASSES.includes(ty.value)) return true;
  }
  for (const q of store.getQuads(null, null, t, null)) {
    if (CONSTRAINT_PREDS.includes(q.predicate.value)) return true;
  }
  return false;
}

let climbPreds = null;
const CLIMB_PREDS = () => (climbPreds
  || (climbPreds = new Set([...ATTACH_PREDS, ODRL + 'action'])));

function holderRoots(store, holder, out, seen) {
  const k = nn(holder);
  if (!k || seen.has(k.value)) return;
  seen.add(k.value);
  let higher = false;
  for (const q of store.getQuads(null, null, k, null)) {
    if (!CLIMB_PREDS().has(q.predicate.value)) continue;
    higher = true;
    holderRoots(store, q.subject, out, seen);
  }
  if (higher) return;
  const name = labelFor(store, k);
  if (name && !out.includes(name)) out.push(name);
}

export function constraintOptions(store) {
  const candidates = new Map();
  for (const pred of CONSTRAINT_PREDS) {
    for (const q of store.getQuads(null, namedNode(pred), null, null)) {
      if (q.object.termType === 'NamedNode') candidates.set(q.object.value, q.object);
    }
  }
  for (const className of CONSTRAINT_CLASSES) {
    for (const q of store.getQuads(null, namedNode(RDF + 'type'), namedNode(className), null)) {
      if (q.subject.termType === 'NamedNode') candidates.set(q.subject.value, q.subject);
    }
  }
  const out = [];
  for (const [iri, t] of candidates) {
    if (!isConstraint(store, t)) continue;
    const provenance = [];
    const seen = new Set();
    for (const q of store.getQuads(null, null, t, null)) {
      if (!CONSTRAINT_PREDS.includes(q.predicate.value)) continue;
      holderRoots(store, q.subject, provenance, seen);
    }
    out.push({ iri, curie: curie(iri), label: labelFor(store, t), provenance });
  }
  return out.sort((a, b) => a.label.localeCompare(b.label, 'nl'));
}

export function attachConstraintCheck(store, holderTerm, predIri, constraintIri) {
  const iri = expandIri(String(constraintIri || '').trim());
  if (!iri || !validIriText(iri)) return { ok: false, reason: 'invalid' };
  const v = namedNode(iri);
  if (!store.getQuads(v, null, null, null).length
      && !store.getQuads(null, null, v, null).length) {
    return { ok: false, reason: 'unknown' };
  }
  const h = nn(holderTerm);
  if (!h) return { ok: false, reason: 'unknown' };
  if (store.getQuads(h, namedNode(predIri), v, null).length) {
    return { ok: false, reason: 'alreadyLinked' };
  }
  if (!CONSTRAINT_PREDS.includes(predIri) || !isConstraint(store, v)) {
    return { ok: false, reason: 'wrongKind' };
  }
  return { ok: true };
}

export function attachConstraint(store, holderTerm, predIri, constraintIri) {
  const verdict = attachConstraintCheck(store, holderTerm, predIri, constraintIri);
  if (!verdict.ok) return verdict;
  const v = namedNode(expandIri(String(constraintIri).trim()));
  store.addQuad(nn(holderTerm), namedNode(predIri), v);
  return { ok: true, term: v };
}

export function addPermission(store, policyTerm, opts = {}) {
  return addRule(store, policyTerm, { className: 'Permission', pred: 'permission' }, opts);
}

export function addProhibition(store, policyTerm, opts = {}) {
  return addRule(store, policyTerm, { className: 'Prohibition', pred: 'prohibition' }, opts);
}

export function addDuty(store, parentTerm, predIri = ODRL + 'obligation') {
  const d = mintBlank(store);
  const a = mintBlank(store);
  store.addQuad(d, namedNode(RDF + 'type'), namedNode(ODRL + 'Duty'));
  store.addQuad(a, namedNode(RDF + 'value'), namedNode(ODRL + 'inform'));
  store.addQuad(d, namedNode(ODRL + 'action'), a);
  store.addQuad(nn(parentTerm), namedNode(predIri), d);
  return d;
}

function groupBase(iri) {
  return iriBase(iri, 'group');
}

function iriBase(iri, word) {
  const m = /^(.*[#/])[^#/]*$/.exec(iri);
  return m ? m[1] + word : iri + '#' + word;
}

export function addPartyCollection(store, subject, predIri) {
  const s = nn(subject);
  const coll = s.termType === 'NamedNode'
    ? namedNode(mintIri(store, groupBase(s.value))) : mintBlank(store);
  store.addQuad(coll, namedNode(RDF + 'type'), namedNode(ODRL + 'PartyCollection'));
  for (const prev of objsOf(store, s, predIri)) {
    if (prev.termType === 'NamedNode') store.addQuad(prev, namedNode(ODRL + 'partOf'), coll);
  }
  removeProp(store, s, predIri);
  store.addQuad(s, namedNode(predIri), coll);
  return coll;
}

export function isPartyCollection(store, term) {
  if (!store || !term) return false;
  return objsOf(store, nn(term), RDF + 'type')
    .some((t) => t.value === ODRL + 'PartyCollection' || t.value === ODRL + 'AssetCollection');
}

export function setAgreementOffer(store, agrTerm, offerIri, knownOfferIris) {
  const known = knownOfferIris instanceof Set ? knownOfferIris : new Set(knownOfferIris || []);
  const sweep = [...PROFILE_PATTERNS.agreementOfferPreds,
    ...PROFILE_PATTERNS.legacyAgreementOfferPreds];
  for (const pred of sweep) {
    for (const q of store.getQuads(nn(agrTerm), namedNode(pred), null, null)) {
      if (q.object.termType === 'NamedNode' && known.has(q.object.value)) store.removeQuad(q);
    }
  }
  const full = expandIri(offerIri);
  if (!full) return;
  for (const pred of PROFILE_PATTERNS.agreementOfferPreds) {
    store.addQuad(nn(agrTerm), namedNode(pred), namedNode(full));
  }
}

export const SKELETON_CLASS = {
  offer: ODRL + 'Offer',
  agreement: ODRL + 'Agreement',
  request: ODRL + 'Request',
  set: ODRL + 'Set',
};

// NAMELESS FIRST (25 Sep 2026). A fresh policy is a BLANK NODE: an invented
// `https://policy.example/new/offer` is a name the reader never chose and has
// to clear before writing their own. Filling the node-id field IS the
// promotion, through the blank->named idiom (`nameNode`).
//
// BARE. The node carries its class and nothing that stands in for a decision:
// no permission, and for an offer no paired agreement. Same reason as the
// withdrawn time condition and prefilled target of 8 Sep — a fabricated
// default reads as something the author put there.
//
// `issued` and `profile` stay: the one is today's date and the other the
// configured profile of this deployment. Both are facts, not stand-ins.
//
// ONE flow for all four categories: `kind` picks the class. A second minting
// path would drift.
export function createSkeleton(store, kind = 'offer') {
  const cls = SKELETON_CLASS[kind] || SKELETON_CLASS.offer;
  const term = mintBlank(store);
  store.addQuad(term, namedNode(RDF + 'type'), namedNode(cls));
  store.addQuad(term, namedNode(DCT + 'issued'), literal(today(), namedNode(XSD + 'date')));
  if (defaultProfile()) {
    store.addQuad(term, namedNode(ODRL + 'profile'), namedNode(defaultProfile()));
  }
  return { term, iri: null };
}

// Wider than SKELETON_CLASS: the + makes only these four, but a loaded source
// may hold any of them, and a blank one of any class is equally unexportable.
const POLICY_CLASSES = [
  ...Object.values(SKELETON_CLASS),
  ODRL + 'Policy', ODRL + 'Privacy', ODRL + 'Ticket', ODRL + 'Assertion',
];

// ODRL IM: a Policy MUST have a uid. A nameless draft cannot carry one, so the
// export marks it non-conformant; this is what the count is read from.
export function unnamedPolicies(store, graphIri) {
  const out = [];
  const seen = new Set();
  for (const cls of POLICY_CLASSES) {
    for (const q of store.getQuads(null, namedNode(RDF + 'type'), namedNode(cls), null)) {
      if (graphIri && ((q.graph && q.graph.value) || '') !== graphIri) continue;
      if (q.subject.termType !== 'BlankNode' || seen.has(q.subject.value)) continue;
      seen.add(q.subject.value);
      out.push(q.subject);
    }
  }
  return out;
}

function isPolicyTerm(store, term) {
  const classes = new Set(POLICY_CLASSES);
  return objsOf(store, nn(term), RDF + 'type').some((t) => classes.has(t.value));
}

export function duplicatePolicy(store, term, newIri) {
  const t = nn(term);
  const iri = newIri || mintIri(store, t.value + '-copy');
  const root = namedNode(iri);
  const bmap = new Map();
  const mt = (x) => {
    if (x.termType === 'BlankNode') {
      if (!bmap.has(x.value)) bmap.set(x.value, mintBlank(store));
      return bmap.get(x.value);
    }
    if (x.termType === 'NamedNode' && x.value === t.value) return root;
    return x;
  };
  for (const q of closureQuads(store, t)) store.addQuad(mt(q.subject), q.predicate, mt(q.object));
  const namePred = [DCT + 'title', RDFS + 'label']
    .find((p) => store.getQuads(root, namedNode(p), null, null).length);
  for (const q of (namePred ? store.getQuads(root, namedNode(namePred), null, null) : [])) {
    store.removeQuad(q);
    store.addQuad(root, q.predicate, literal(q.object.value + COPY_SUFFIX, q.object.language || undefined));
  }
  return iri;
}

export function duplicateAttached(store, parentTerm, predIri, term) {
  const t = nn(term);
  const bmap = new Map();
  const mt = (x) => {
    if (x.termType === 'BlankNode') {
      if (!bmap.has(x.value)) bmap.set(x.value, mintBlank(store));
      return bmap.get(x.value);
    }
    return x;
  };
  if (t.termType === 'BlankNode') {
    for (const q of closureQuads(store, t)) store.addQuad(mt(q.subject), q.predicate, mt(q.object));
    const copy = mt(t);
    store.addQuad(nn(parentTerm), namedNode(predIri), copy);
    return copy;
  }
  const iri = duplicatePolicy(store, t);
  store.addQuad(nn(parentTerm), namedNode(predIri), namedNode(iri));
  return namedNode(iri);
}

const REALISATION_PRED = PREFIXES.prov + 'wasDerivedFrom';

export function removeIncomingRealisations(store, term) {
  const gone = store.getQuads(null, namedNode(REALISATION_PRED), nn(term), null);
  store.removeQuads(gone);
  return gone.length;
}

export const ATTACH_PREDS = [
  ODRL + 'permission', ODRL + 'prohibition', ODRL + 'obligation',
  ODRL + 'duty', ODRL + 'consequence',
];

export function policyClearQuads(store, term) {
  const t = nn(term);
  const gone = [];
  const goneKeys = new Set();
  const add = (q) => {
    const k = N3.termToId(q.subject) + '\u0000' + N3.termToId(q.predicate)
      + '\u0000' + N3.termToId(q.object) + '\u0000' + N3.termToId(q.graph);
    if (goneKeys.has(k)) return;
    goneKeys.add(k);
    gone.push(q);
  };
  const planned = new Set();
  const keyOf = (x) => x.termType + ':' + x.value;
  const clear = (node) => {
    if (planned.has(keyOf(node))) return;
    planned.add(keyOf(node));
    const children = [];
    for (const pred of ATTACH_PREDS) {
      for (const q of store.getQuads(node, namedNode(pred), null, null)) {
        if (q.object.termType === 'NamedNode') children.push(q.object);
      }
    }
    for (const q of store.getQuads(null, null, node, null)) add(q);
    for (const q of closureQuads(store, node)) add(q);
    for (const k of children) {
      const others = store.getQuads(null, null, k, null).filter((q) => {
        if (q.predicate.value === REALISATION_PRED) return false;
        if (q.subject.termType === k.termType && q.subject.value === k.value) return false;
        return !planned.has(keyOf(q.subject));
      });
      if (!others.length) clear(k);
    }
  };
  clear(t);
  return gone;
}

// Only rules and duties that hang on nothing else go along; a shared rule stays,
// otherwise deleting one policy wrecks another.
export function removePolicy(store, term) {
  store.removeQuads(policyClearQuads(store, term));
}

export function removeAttached(store, parentTerm, predIri, term) {
  const t = nn(term);
  store.removeQuads(store.getQuads(nn(parentTerm), namedNode(predIri), t, null));
  const external = store.getQuads(null, null, t, null)
    .filter((q) => !(q.subject.termType === t.termType && q.subject.value === t.value))
    .filter((q) => q.predicate.value !== REALISATION_PRED);
  if (external.length === 0) {
    removeIncomingRealisations(store, t);
    store.removeQuads(store.getQuads(null, null, t, null));
    store.removeQuads(closureQuads(store, t));
  }
}

export function renameQuads(store, iri) {
  return nodePositions(store, namedNode(expandIri(iri)));
}

export function nodePositions(store, term) {
  const t = nn(term);
  const out = [];
  const seen = new Set();
  const add = (q) => {
    const k = N3.termToId(q.subject) + '\u0000' + N3.termToId(q.predicate)
      + '\u0000' + N3.termToId(q.object) + '\u0000' + N3.termToId(q.graph);
    if (seen.has(k)) return;
    seen.add(k);
    out.push(q);
  };
  for (const q of store.getQuads(t, null, null, null)) add(q);
  for (const q of store.getQuads(null, null, t, null)) add(q);
  return out;
}

// ALL positions or none: a rename that misses the reference from another policy
// leaves a dangling link that only surfaces on the next load.
export function renameNode(store, oldIri, newIri) {
  const verdict = renameCheck(store, oldIri, newIri);
  if (!verdict.ok || verdict.count === 0) return verdict;
  const from = expandIri(oldIri);
  const to = namedNode(expandIri(newIri));
  const touched = renameQuads(store, from);
  const swap = (x) => (x.termType === 'NamedNode' && x.value === from ? to : x);
  store.removeQuads(touched);
  for (const q of touched) {
    store.addQuad(swap(q.subject), q.predicate, swap(q.object), q.graph);
  }
  return { ok: true, count: touched.length };
}

export function renameCheck(store, oldIri, newIri) {
  const from = expandIri(oldIri);
  const to = expandIri(newIri);
  if (!to || !validIriText(to)) return { ok: false, reason: 'invalid' };
  if (!from) return { ok: false, reason: 'unknown' };
  if (from === to) return { ok: true, count: 0 };
  const toTerm = namedNode(to);
  if (store.getQuads(toTerm, null, null, null).length
      || store.getQuads(null, null, toTerm, null).length) {
    return { ok: false, reason: 'taken' };
  }
  const touched = renameQuads(store, from);
  if (!touched.length) return { ok: false, reason: 'unknown' };
  return { ok: true, count: touched.length };
}

export function nameCheck(store, blank, newIri) {
  const t = nn(blank);
  if (!t || t.termType !== 'BlankNode') return { ok: false, reason: 'notBlank' };
  const to = expandIri(String(newIri || '').trim());
  if (!to || !validIriText(to)) return { ok: false, reason: 'invalid' };
  const toTerm = namedNode(to);
  if (store.getQuads(toTerm, null, null, null).length
      || store.getQuads(null, null, toTerm, null).length) {
    return { ok: false, reason: 'taken' };
  }
  const touched = nodePositions(store, t);
  if (!touched.length) return { ok: false, reason: 'unknown' };
  return { ok: true, count: touched.length };
}

export function nameNode(store, blank, newIri) {
  const verdict = nameCheck(store, blank, newIri);
  if (!verdict.ok) return verdict;
  const from = nn(blank);
  const to = namedNode(expandIri(String(newIri).trim()));
  const policy = isPolicyTerm(store, from);
  const touched = nodePositions(store, from);
  const swap = (x) => (x.termType === 'BlankNode' && x.value === from.value ? to : x);
  store.removeQuads(touched);
  for (const q of touched) {
    store.addQuad(swap(q.subject), q.predicate, swap(q.object), q.graph);
  }
  // A policy that gains a name gains the uid the ODRL IM requires of it — the
  // promotion is what makes the draft conformant, so it completes it here
  // rather than leaving a second thing for the author to remember.
  if (policy && !objsOf(store, to, ODRL + 'uid').length) {
    store.addQuad(to, namedNode(ODRL + 'uid'), to);
  }
  return { ok: true, count: touched.length };
}

export function nameSuggestion(store, blank) {
  const t = nn(blank);
  if (!t || t.termType !== 'BlankNode') return '';
  let base = '';
  const seen = new Set([t.value]);
  const queue = [t];
  while (queue.length && !base) {
    const current = queue.shift();
    for (const q of store.getQuads(null, null, current, null)) {
      if (q.subject.termType === 'NamedNode') { base = q.subject.value; break; }
      if (q.subject.termType === 'BlankNode' && !seen.has(q.subject.value)) {
        seen.add(q.subject.value);
        queue.push(q.subject);
      }
    }
  }
  if (!base) return '';
  const ty = objOf(store, t, RDF + 'type');
  const word = ty ? localName(ty.value).toLowerCase() : 'node';
  return mintIri(store, iriBase(base, word));
}

export function replaceSubjectClosure(store, subject, turtleText) {
  const t = nn(subject);
  const header = Object.entries(allPrefixes()).map(([p, iri]) => `@prefix ${p}: <${iri}> .`).join('\n');
  const headerLines = header.split('\n').length;
  let quads;
  try {
    quads = new Parser().parse(header + '\n' + turtleText);
  } catch (e) {
    const msg = String(e.message || e).replace(/line (\d+)/, (_, n) => 'line ' + Math.max(1, Number(n) - headerLines));
    return { ok: false, error: msg };
  }
  const fresh = new Map();
  const renumber = (x) => {
    if (x.termType !== 'BlankNode') return x;
    if (!fresh.has(x.value)) fresh.set(x.value, mintBlank(store));
    return fresh.get(x.value);
  };
  quads = quads.map((q) => (q.subject.termType === 'BlankNode'
    || q.object.termType === 'BlankNode' || q.graph.termType === 'BlankNode'
    ? N3.DataFactory.quad(renumber(q.subject), q.predicate, renumber(q.object), renumber(q.graph)) : q));

  const old = closureQuads(store, t);
  const containsSubject = t.termType !== 'NamedNode'
    || quads.some((q) => q.subject.termType === 'NamedNode' && q.subject.value === t.value);
  store.removeQuads(old);
  store.addQuads(quads);
  return { ok: true, removed: old.length, added: quads.length, containsSubject };
}

export function exportTurtle(store, { graph = null } = {}) {
  const writer = new N3.Writer({ prefixes: allPrefixes() });
  const quads = graph
    ? store.getQuads(null, null, null, namedNode(graph))
    : store.getQuads(null, null, null, null);
  writer.addQuads(dedupeTriples(quads));
  let out = '';
  writer.end((err, result) => { if (!err) out = result; });
  return prunePrefixes(out);
}

function graphStore(store, graph) {
  const out = new Store();
  out.addQuads(dedupeTriples(store.getQuads(null, null, null, namedNode(graph))));
  return out;
}

export function exportJsonLd(store, { graph = null } = {}) {
  if (graph) store = graphStore(store, graph);
  const all = store.getQuads(null, null, null, null);
  const asObject = new Set(all.filter((q) => q.object.termType === 'BlankNode')
    .map((q) => q.object.value));
  const tops = new Map();
  for (const q of all) {
    if (q.subject.termType === 'BlankNode' && asObject.has(q.subject.value)) continue;
    const key = q.subject.termType + ':' + q.subject.value;
    if (!tops.has(key)) tops.set(key, q.subject);
  }
  const bodies = [...tops.values()].map((s) => subjectJsonLdBody(store, s));
  return JSON.stringify({ '@context': jsonLdContext(bodies), '@graph': bodies }, null, 2);
}

export { termKey };

function inOwnClosure(store, root, candidate) {
  const kS = termKey(candidate);
  if (termKey(root) === kS) return true;
  for (const q of closureQuads(store, root)) {
    if (termKey(q.object) === kS) return true;
  }
  return false;
}

export function moveAttached(store, fromParent, fromPred, term, toParent, toPred) {
  const fp = nn(fromParent);
  const tp = nn(toParent);
  const t0 = nn(term);
  const fPred = typeof fromPred === 'string' ? fromPred : fromPred.value;
  const tPred = typeof toPred === 'string' ? toPred : toPred.value;
  const existing = store.getQuads(fp, namedNode(fPred), t0, null);
  if (!existing.length) {
    throw new Error('moveAttached: no existing link to move');
  }
  const samePlace = fp.termType === tp.termType && fp.value === tp.value && fPred === tPred;
  if (samePlace) return;
  if (inOwnClosure(store, t0, tp)) {
    throw new Error('moveAttached: a node cannot hang inside its own closure (a cycle)');
  }
  store.removeQuads(existing);
  store.addQuad(tp, namedNode(tPred), t0);
}

export function linkAttached(store, toParent, toPred, term) {
  const tPred = typeof toPred === 'string' ? toPred : toPred.value;
  store.addQuad(nn(toParent), namedNode(tPred), nn(term));
}

function attachmentPoint(store, spec) {
  const p = nn(spec.parent);
  if (spec.pred === 'refinement') {
    return { holder: ensureActionNode(store, p), predIri: ODRL + 'refinement' };
  }
  return { holder: p, predIri: ODRL + 'constraint' };
}

export function moveConstraint(store, from, cTerm, to, opts = {}) {
  const t0 = nn(cTerm);
  const target = attachmentPoint(store, to);
  if (opts.copy) {
    linkAttached(store, target.holder, target.predIri, t0);
    return;
  }
  const source = attachmentPoint(store, from);
  moveAttached(store, source.holder, source.predIri, t0, target.holder, target.predIri);
}

export const DRAGITEM = { NODE: 'node', CONSTRAINT: 'constraint' };
export const DROPTARGET = { CARD: 'card', RULE: 'rule', ACTION: 'action' };

const RULE_PREDS = new Set([ODRL + 'permission', ODRL + 'prohibition']);

function allPolicies(model) {
  return [...(model.sets || []), ...(model.offers || []), ...(model.agreements || [])];
}
function allRules(model) {
  const out = [];
  for (const p of allPolicies(model)) {
    for (const r of (p.permissions || [])) out.push(r);
    for (const r of (p.prohibitions || [])) out.push(r);
  }
  return out;
}

function allRuleLike(model) {
  const out = [];
  const seen = new Set();
  const add = (r) => {
    if (!r || !r.term || seen.has(termKey(r.term))) return;
    seen.add(termKey(r.term));
    out.push(r);
    for (const d of (r.duties || [])) add(d);
    for (const d of (r.obligations || [])) add(d);
  };
  for (const p of allPolicies(model)) {
    for (const r of (p.permissions || [])) add(r);
    for (const r of (p.prohibitions || [])) add(r);
    for (const d of (p.obligations || [])) add(d);
  }
  return out;
}

export function validDropTargets(model, item, opts = {}) {
  if (!model || !item || !item.term) return [];
  const allowed = typeof opts.allow === 'function' ? opts.allow : () => true;
  const samePlace = (term, pred) => item.parent
    && termKey(term) === termKey(item.parent) && pred === item.pred;
  const out = [];
  const add = (kind, term, pred) => {
    if (samePlace(term, pred)) return;
    if (termKey(term) === termKey(item.term)) return;
    if (!allowed(term, kind, pred)) return;
    out.push({ kind, term, pred });
  };
  if (item.kind === DRAGITEM.CONSTRAINT) {
    for (const r of allRuleLike(model)) {
      add(DROPTARGET.RULE, r.term, 'constraint');
      add(DROPTARGET.ACTION, r.term, 'refinement');
    }
    return out;
  }
  if (RULE_PREDS.has(item.pred)) {
    for (const p of allPolicies(model)) add(DROPTARGET.CARD, p.term, item.pred);
    return out;
  }
  for (const p of allPolicies(model)) add(DROPTARGET.CARD, p.term, ODRL + 'obligation');
  for (const r of allRules(model)) add(DROPTARGET.RULE, r.term, ODRL + 'duty');
  return out;
}

const KNOWN_ACTIONS = ['use', 'read', 'distribute', 'reproduce', 'modify', 'delete', 'inform']
  .map((l) => ODRL + l);
const KNOWN_OPERATORS = ['eq', 'neq', 'gt', 'gteq', 'lt', 'lteq', 'isA', 'hasPart', 'isPartOf', 'isAllOf', 'isAnyOf']
  .map((l) => ODRL + l);
const KNOWN_LEFT_OPERANDS = [ODRL + 'purpose', ODRL + 'dateTime', ODRL + 'count'];

export function REGISTER_PARTY_BASES() {
  return editProfile().partyRegisterBases;
}

const TYPE_CANDIDATE = [
  [ODRL + 'Action', 'actions'], [ODRL + 'Operator', 'operators'],
  [ODRL + 'LeftOperand', 'leftOperands'],
  [ODRL + 'Party', 'parties'], [ODRL + 'PartyCollection', 'parties'],
  [FOAF + 'Organization', 'parties'], [FOAF + 'Agent', 'parties'],
  [ODRL + 'Asset', 'targets'], [ODRL + 'AssetCollection', 'targets'],
  [DCAT + 'Dataset', 'targets'], [DCAT + 'Distribution', 'targets'],
  [DPV + 'Purpose', 'purposes'],
];

export function termOptions(store) {
  const mk = () => new Map();
  const add = (map, iri) => {
    if (!iri || map.has(iri)) return;
    map.set(iri, { iri, curie: curie(iri), label: labelFor(store, namedNode(iri)) });
  };
  const actions = mk(); const operators = mk(); const leftOperands = mk();
  const parties = mk(); const targets = mk(); const purposes = mk(); const labeled = mk();

  KNOWN_ACTIONS.forEach((i) => add(actions, i));
  KNOWN_OPERATORS.forEach((i) => add(operators, i));
  KNOWN_LEFT_OPERANDS.forEach((i) => add(leftOperands, i));
  editProfile().operators.forEach((i) => add(operators, i));
  editProfile().leftOperands.forEach((i) => add(leftOperands, i));

  const byName = {
    actions, operators, leftOperands, parties, targets, purposes, labeled,
  };
  for (const [ty, name] of TYPE_CANDIDATE) {
    for (const q of store.getQuads(null, namedNode(RDF + 'type'), namedNode(ty), null)) {
      if (q.subject.termType === 'NamedNode') add(byName[name], q.subject.value);
    }
  }
  const usedIn = [
    [ODRL + 'operator', operators], [ODRL + 'leftOperand', leftOperands],
    [ODRL + 'action', actions], [RDF + 'value', actions],
    [ODRL + 'assigner', parties], [ODRL + 'assignee', parties],
    [DCT + 'publisher', parties], [ODRL + 'informedParty', parties],
  ];
  for (const [pred, map] of usedIn) {
    for (const q of store.getQuads(null, namedNode(pred), null, null)) {
      if (q.object.termType === 'NamedNode') add(map, q.object.value);
    }
  }
  for (const pred of targetPreds(store)) {
    for (const q of store.getQuads(null, namedNode(pred), null, null)) {
      if (q.object.termType === 'NamedNode') add(targets, q.object.value);
    }
  }
  for (const q of store.getQuads(null, namedNode(ODRL + 'leftOperand'), namedNode(ODRL + 'purpose'), null)) {
    const right = objOf(store, q.subject, ODRL + 'rightOperand');
    if (right && right.termType === 'NamedNode') add(purposes, right.value);
  }
  const partyBases = REGISTER_PARTY_BASES();
  for (const q of store.getQuads(null, namedNode(RDFS + 'label'), null, null)) {
    if (q.subject.termType !== 'NamedNode') continue;
    add(labeled, q.subject.value);
    if (partyBases.some((b) => q.subject.value.startsWith(b))) {
      add(parties, q.subject.value);
    }
  }
  const sort = (map) => [...map.values()].sort((a, b) => a.label.localeCompare(b.label, 'nl'));
  return {
    actions: sort(actions), operators: sort(operators), leftOperands: sort(leftOperands),
    parties: sort(parties), targets: sort(targets), purposes: sort(purposes), labeled: sort(labeled),
  };
}

export function newStore() {
  return new Store();
}
